//! The three shortcuts and the setup guide in the bridge folder's `快捷指令/`.
//!
//! The shortcut sources are XML property lists in the repository's
//! `shortcuts/` folder (generated by `scripts/build-shortcuts.mjs`, no
//! personal data in them) and embedded in the app. iOS only imports signed
//! shortcuts, so the app signs them on this Mac with
//! `shortcuts sign --mode anyone` and puts the signed files next to the
//! guide. A shortcut is signed again only when its source changed or its
//! file is missing; when signing does not work the guide explains how to
//! build the shortcuts by hand.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::Duration;

use sha2::{Digest, Sha256};

use crate::kb::{files, git};

/// One shortcut: its name (also the file name on the phone) and its source.
pub struct Source {
    pub name: &'static str,
    pub plist: &'static str,
}

pub const SOURCES: &[Source] = &[
    Source {
        name: "记一笔",
        plist: include_str!("../../../shortcuts/记一笔.plist"),
    },
    Source {
        name: "看底色",
        plist: include_str!("../../../shortcuts/看底色.plist"),
    },
    Source {
        name: "答裁决",
        plist: include_str!("../../../shortcuts/答裁决.plist"),
    },
];

/// The guide, viewable on the phone.
pub const GUIDE_NAME: &str = "使用说明.html";
pub const GUIDE: &str = include_str!("../../../shortcuts/使用说明.html");
/// What the app remembers about the signed files (in its own folder).
pub const STATE_FILE: &str = "iphone-shortcuts.json";

/// What putting the shortcuts in place did.
#[derive(Debug, Default, PartialEq, Eq)]
pub struct Installed {
    pub signed: Vec<&'static str>,
    pub kept: usize,
    pub failed: Vec<(&'static str, String)>,
    pub guide_written: bool,
}

fn source_hash(source: &Source) -> String {
    Sha256::digest(source.plist.as_bytes())
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

/// Puts the guide and the signed shortcuts into `folder`. `sign` turns one
/// XML source into a signed file at the given path.
pub fn install(
    folder: &Path,
    state_file: Option<&Path>,
    sign: &dyn Fn(&str, &Path) -> Result<(), String>,
) -> Installed {
    let mut installed = Installed::default();
    let guide = folder.join(GUIDE_NAME);
    if !fs::read(&guide).is_ok_and(|bytes| bytes == GUIDE.as_bytes()) {
        match files::write_atomic(&guide, GUIDE) {
            Ok(()) => installed.guide_written = true,
            Err(error) => log::warn!("iphone: the guide could not be written ({error})"),
        }
    }

    let mut state: BTreeMap<String, String> = state_file
        .and_then(|file| fs::read_to_string(file).ok())
        .and_then(|text| serde_json::from_str(&text).ok())
        .unwrap_or_default();
    for source in SOURCES {
        let target = folder.join(format!("{}.shortcut", source.name));
        let hash = source_hash(source);
        if target.is_file() && state.get(source.name) == Some(&hash) {
            installed.kept += 1;
            continue;
        }
        let temp = folder.join(format!(".{}.shortcut.signing", source.name));
        let _ = fs::remove_file(&temp);
        let result = sign(source.plist, &temp).and_then(|()| {
            fs::rename(&temp, &target).map_err(|error| format!("没能放好签好的文件（{error}）"))
        });
        let _ = fs::remove_file(&temp);
        match result {
            Ok(()) => {
                state.insert(source.name.to_string(), hash);
                installed.signed.push(source.name);
            }
            Err(error) => installed.failed.push((source.name, error)),
        }
    }
    if let Some(file) = state_file {
        if let Ok(text) = serde_json::to_string_pretty(&state) {
            if let Err(error) = files::write_atomic(file, &format!("{text}\n")) {
                log::warn!("iphone: the shortcut record could not be saved ({error})");
            }
        }
    }
    installed
}

const PLUTIL: &str = "/usr/bin/plutil";
const SHORTCUTS: &str = "/usr/bin/shortcuts";
const CONVERT_TIMEOUT: Duration = Duration::from_secs(30);
const SIGN_TIMEOUT: Duration = Duration::from_secs(120);

/// Signs one shortcut with the system's tools: `plutil` makes the binary
/// property list `shortcuts sign` wants, which signs it for anyone to import.
pub fn sign_with_system(xml: &str, output: &Path) -> Result<(), String> {
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let work = std::env::temp_dir().join(format!(
        "dise-shortcut-{}-{}",
        std::process::id(),
        COUNTER.fetch_add(1, Ordering::Relaxed)
    ));
    fs::create_dir_all(&work).map_err(|error| format!("没能建立临时文件夹（{error}）"))?;
    let result = sign_in(&work, xml, output);
    let _ = fs::remove_dir_all(&work);
    result
}

fn sign_in(work: &Path, xml: &str, output: &Path) -> Result<(), String> {
    let source: PathBuf = work.join("source.plist");
    let binary: PathBuf = work.join("unsigned.shortcut");
    fs::write(&source, xml).map_err(|error| format!("没能写出临时文件（{error}）"))?;

    let mut convert = Command::new(PLUTIL);
    convert
        .args(["-convert", "binary1", "-o"])
        .arg(&binary)
        .arg(&source);
    let done = git::finish(convert, CONVERT_TIMEOUT)?;
    if !done.success() {
        return Err(format!("plutil 没能转换：{}", done.detail()));
    }

    let mut sign = Command::new(SHORTCUTS);
    sign.args(["sign", "--mode", "anyone", "--input"])
        .arg(&binary)
        .arg("--output")
        .arg(output);
    let done = git::finish(sign, SIGN_TIMEOUT)?;
    if done.timed_out {
        return Err("shortcuts sign 超时了".to_string());
    }
    // `shortcuts sign` prints harmless warnings and may exit 0 without
    // writing anything: the signed file itself is what counts.
    match fs::read(output) {
        Ok(bytes) if bytes.starts_with(b"AEA1") => Ok(()),
        _ => Err(format!(
            "shortcuts sign 没有签好：{}",
            done.stderr
                .lines()
                .filter(|line| !line.contains("Unrecognized attribute string flag"))
                .collect::<Vec<_>>()
                .join(" ")
                .trim()
        )),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::kb::test_support::TempDir;
    use std::cell::RefCell;

    #[test]
    fn the_sources_are_shortcuts_without_personal_paths() {
        for source in SOURCES {
            assert!(source.plist.starts_with("<?xml"), "{}", source.name);
            assert!(
                source.plist.contains("WFWorkflowActions"),
                "{}",
                source.name
            );
            assert!(!source.plist.contains("/Users/"), "{}", source.name);
            assert!(source.plist.contains("底色/"), "{}", source.name);
        }
        for name in ["记一笔", "看底色", "答裁决"] {
            assert!(GUIDE.contains(name), "{name}");
        }
        assert!(!GUIDE.contains("<script"));
    }

    #[test]
    fn signs_once_and_again_only_when_needed() {
        let dir = TempDir::new("shortcuts");
        let folder = dir.mkdir("快捷指令");
        let state = dir.path().join("app/iphone-shortcuts.json");
        fs::create_dir_all(state.parent().unwrap()).unwrap();
        let calls = RefCell::new(0);
        let sign = |xml: &str, out: &Path| {
            *calls.borrow_mut() += 1;
            fs::write(out, format!("AEA1{}", xml.len())).map_err(|e| e.to_string())
        };
        let first = install(&folder, Some(&state), &sign);
        assert_eq!(first.signed, ["记一笔", "看底色", "答裁决"]);
        assert!(first.guide_written);
        assert!(folder.join("记一笔.shortcut").is_file());
        assert_eq!(fs::read_to_string(folder.join(GUIDE_NAME)).unwrap(), GUIDE);

        let second = install(&folder, Some(&state), &sign);
        assert_eq!(
            second,
            Installed {
                kept: 3,
                ..Installed::default()
            }
        );
        assert_eq!(*calls.borrow(), 3);

        fs::remove_file(folder.join("看底色.shortcut")).unwrap();
        let third = install(&folder, Some(&state), &sign);
        assert_eq!(third.signed, ["看底色"]);

        let failing = |_: &str, _: &Path| Err("没有网".to_string());
        fs::remove_file(folder.join("答裁决.shortcut")).unwrap();
        let fourth = install(&folder, Some(&state), &failing);
        assert_eq!(fourth.failed, [("答裁决", "没有网".to_string())]);
        // Nothing half-signed is left behind.
        let names: Vec<String> = fs::read_dir(&folder)
            .unwrap()
            .flatten()
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .collect();
        assert!(names.iter().all(|name| !name.starts_with('.')), "{names:?}");
    }

    /// Signs the real sources with the system's tools (macOS only, and only
    /// when `DISE_TEST_SIGN=1`: it talks to the Shortcuts service).
    #[test]
    fn the_sources_can_be_signed_on_this_mac() {
        if std::env::var("DISE_TEST_SIGN").as_deref() != Ok("1") || !Path::new(SHORTCUTS).exists() {
            return;
        }
        let dir = TempDir::new("shortcuts-sign");
        for source in SOURCES {
            let out = dir.path().join(format!("{}.shortcut", source.name));
            sign_with_system(source.plist, &out).unwrap_or_else(|e| panic!("{}: {e}", source.name));
            assert!(fs::read(&out).unwrap().starts_with(b"AEA1"));
        }
    }
}
